//! Boys function accuracy against 50-digit mpmath reference values
//! (generated by tests/reference/gen_boys.py).

use hf_rs::integrals::{boys, boys_array, BOYS_MAX_M};

#[test]
fn boys_matches_mpmath_reference() {
    let data: serde_json::Value =
        serde_json::from_str(include_str!("data/boys_reference.json")).unwrap();
    let mut worst = (0.0_f64, 0usize, 0.0_f64);
    for row in data["rows"].as_array().unwrap() {
        let t = row["t"].as_f64().unwrap();
        let refs: Vec<f64> = row["f"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap().parse::<f64>().unwrap())
            .collect();
        let mut out = [0.0; BOYS_MAX_M + 1];
        boys_array(BOYS_MAX_M, t, &mut out);
        for (n, &r) in refs.iter().enumerate() {
            let rel = ((out[n] - r) / r).abs();
            if rel > worst.0 {
                worst = (rel, n, t);
            }
            assert!(
                rel <= 1e-14,
                "F_{}({}) = {:.17e}, reference {:.17e}, rel. error {:.2e}",
                n, t, out[n], r, rel
            );
            assert_eq!(boys(n, t), out[n]);
        }
    }
    println!("worst relative error {:.3e} at n = {}, T = {}", worst.0, worst.1, worst.2);
}
